mapper.select:
select o.id, o.customer_id, o.process_id, order_date, product_name, spec_1, spec_2, special_unit_price, quantity, amount, o.remark, is_deleted, print_count, o.create_time, o.update_time, c.name customer_name, p.name process_name, cp.fake_unit_price unit_price from biz_order o left join biz_customer c on o.customer_id = c.id left join biz_process p on o.process_id = p.id left join biz_customer_process_price cp on o.customer_id = cp.customer_id and o.process_id = cp.process_id
o.is_deleted = 0
and o.id = #{param.id}
and o.customer_id = #{param.customerId}
and o.process_id = #{param.processId}
and product_name like concat('%', #{param.productName}, '%')
and order_date between #{param.beginDate} and #{param.endDate}
and special_unit_price is not null
and amount between #{param.beginAmount} and #{param.endAmount}
and print_count = 0
and print_count > 0
order by o.id desc

select o.id, o.customer_id, o.process_id, order_date, product_name, spec_1, spec_2, special_unit_price, quantity, amount, o.remark, is_deleted, print_count, o.create_time, o.update_time, c.name customer_name, p.name process_name, cp.fake_unit_price unit_price from biz_order o left join biz_customer c on o.customer_id = c.id left join biz_process p on o.process_id = p.id left join biz_customer_process_price cp on o.customer_id = cp.customer_id and o.process_id = cp.process_id where o.id in
#{id}
order by o.id

select o.id, o.customer_id, o.process_id, order_date, product_name, spec_1, spec_2, special_unit_price, quantity, amount, o.remark, is_deleted, print_count, o.create_time, o.update_time, c.name customer_name, p.name process_name, cp.real_unit_price unit_price from biz_order o left join biz_customer c on o.customer_id = c.id left join biz_process p on o.process_id = p.id left join biz_customer_process_price cp on o.customer_id = cp.customer_id and o.process_id = cp.process_id
o.is_deleted = 0 and order_date between #{beginDate} and #{endDate}
and o.customer_id = #{customerId}
order by o.customer_id, o.order_date

select product_name, spec_1, spec_2 from biz_order
where customer_id = #{customerId}
and process_id = #{processId}
and product_name like concat('%', #{productName}, '%')
order by order_date desc
limit 10
